window.APP_ESSAY_PAPERS = window.APP_ESSAY_PAPERS || {};
window.APP_ESSAY_PAPERS["gao1-毒理學"] = [{"roc":114,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114080&c=283&s=2816&q=1","qs":[{"n":1,"q":"在 1950s 末至 1960s 初曾發生過使用一個新開發出來之藥物於懷孕婦女而導致嚴重致畸胎事件。請說明此事件原由及對後續臨床前毒性試驗有何影響？（10 分）以及目前有關化學物質致畸胎毒理測試原理與方法。（15 分）","pt":25},{"n":2,"q":"請說明毒物代謝動力學（Toxicokinetics）及毒物效應動力學（Toxicodynamics）之區別，包括兩者之定義及所屬之範疇。（25 分）","pt":25},{"n":3,"q":"1984 年在印度波帕市（Bhopal）一個製造加保利農藥（carbaryl）工廠，此農藥前驅物為異氰酸甲酯（或稱甲基異氰酸酯；methyl isocyanate），因異氰酸甲酯儲存槽爆炸而大量漏出，影響數十萬人，造成數萬人死亡。請說明為何異氰酸甲酯會造成如此重大的傷亡？請就暴露途徑、毒物性質和毒理作用說明。  （25 分）","pt":25},{"n":4,"q":"毒性物質進入生物體後會進行吸收、分布、代謝及排除，這些過程中必須進出細胞膜。請說明毒性物質穿越細胞膜的機制有那幾種？（25 分）","pt":25}]},{"roc":113,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113080&c=380&s=2916&q=1","qs":[{"n":1,"q":"請說明毒性物質於人體之三種主要吸收之曝露途徑，並比較此三種曝露途徑吸收效率之差異。（25 分）","pt":25},{"n":2,"q":"毒性物質於人體導致癌症共可分類為三種致癌物：致基因毒性致癌物（genotoxic carcinogen）、原發性致癌物（epigenetic carcinogen）及完全致癌物（complete carcinogen），請說明戴奧辛（dioxins）屬於那一類致癌物，並解釋其原因。          （25 分）","pt":25},{"n":3,"q":"汞（mercury, Hg）亦稱為水銀，以三種型態存在於環境中：汞元素態（金屬態）、無機汞及有機類汞。基於汞對人體及生物體之毒性風險高，因此汞水俣公約（Minamata Convention on Mercury）於 2009 年通過決議，制定有法律約束關於全球汞問題的國際公約。請說明三種型態之汞對於人體之曝露途徑、標的器官及健康風險。（25 分）","pt":25},{"n":4,"q":"毒性物質之毒性強度、標的器官及機制，通常會透過流行病學，活體動物實驗及活體外細胞毒性試驗進行評估。其中活體動物實驗需有三大假設必須滿足，才能將活體動物實驗數據外插至人體作為訂定毒性物質管制標準之應用，請說明此三大假設為何？（25 分）","pt":25}]},{"roc":112,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112090&c=380&s=3108&q=1","qs":[{"n":1,"q":"全氟辛烷磺酸、石棉及皂黃等物質的毒性化學物質分類為何？並就其如何被人體吸收、分布、代謝及排除等作用進行說明。（30分）","pt":30},{"n":2,"q":"孟加拉1990年代發生史上最大規模的集體人口中毒事件，主要是井水中受到污染物影響，請說明其發生的人體病變及污染物名稱為何？若比較其中毒事件與臺灣日治時期發生臺南嘉義的中毒事件，試比較其污染來源之差異性。（25分）","pt":25},{"n":3,"q":"請說明美國環保署對於生態風險之定義為何？另請說明我國健康風險評估技術之基本步驟及內容。（25分）","pt":25},{"n":4,"q":"菸草中的尼古丁是成癮物質，亦為癮君子抽菸的主要原因。尼古丁有兩個酸解離常數（pKa），其中之一的pKa約為7.8。在臺灣嚼食檳榔（3分鐘內）口腔中的pH可達到9-11。請由以上數據來闡明為何臺灣嚼食檳榔者幾乎都抽菸？（20分）","pt":20}]},{"roc":111,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111090&c=377&s=2009&q=1","qs":[{"n":1,"q":"請說明何謂劑量效應曲線（dose-response curve），並說明如何利用劑量效應曲線進行毒性評估。（25 分）","pt":25},{"n":2,"q":"請詳細並舉例說明不同化學物質共同暴露時，可能產生之毒性交互作用包括那幾種。（25 分）","pt":25},{"n":3,"q":"請說明有機磷農藥及氨基甲酸鹽農藥暴露所可能造成之毒性作用機轉及健康影響分別為何。（25 分）","pt":25},{"n":4,"q":"請說明游離輻射與非游離輻射之差別為何，並說明非游離輻射暴露所可能造成之不良健康效應。（25 分）","pt":25}]},{"roc":110,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110090&c=384&s=1525&q=1","qs":[{"n":1,"q":"說明何謂亨利常數（Henry’s Law Constant, KH）與辛醇/水分布係數 Kow（octanol/water partition coefficient），並指出毒性物質之數值大小所代表的意義。（20 分）","pt":20},{"n":2,"q":"說明持久性有機污染物（Persistent Organic Pollutants, POPs）之定義、主要特性以及對人體的危害。（30 分）","pt":30},{"n":3,"q":"試說明若欲對毒性物質進行各種毒性測試方法，其優先順序為何？（25 分）","pt":25},{"n":4,"q":"生物個體對毒性物質的反應受到許多因素所影響，試說明影響毒性之生物體因素。（25 分）","pt":25}]},{"roc":109,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109090&c=389&s=1704&q=1","qs":[{"n":1,"q":"請描述工程奈米微粒的來源、暴露、毒性及機制，並舉例說明。（25分）","pt":25},{"n":2,"q":"請舉例詳細說明化學物質如何活化產生基因突變。（25分）","pt":25},{"n":3,"q":"請舉出三種造成慢性腎臟疾病的重金屬，並詳細說明其來源、毒性及機制。（25分）","pt":25},{"n":4,"q":"請詳細說明國際癌症總署（IARC）關於致癌物分類標準，並舉例說明。（25分）","pt":25}]},{"roc":108,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108090&c=296&s=1704&q=1","qs":[{"n":1,"q":"請敘述致癌作用三階段及各舉一致癌物為範例。（25 分）","pt":25},{"n":2,"q":"請敘述金屬鎘與有機汞對人體危害之環境污染事件並比較其致毒作用機制之差異。（25 分）","pt":25},{"n":3,"q":"請敘述飲用水水質污染物質微囊藻毒（microcystins or cyanoginosins）由何而來？微囊藻毒對人類健康風險中主要之標的器官為何？（25 分）","pt":25},{"n":4,"q":"請敘述戴奧辛（dioxins）之過去及現在之主要污染源為何？並解釋其對人類所產生毒性及其致毒機制。（25 分）","pt":25}]},{"roc":107,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107090&c=392&s=1704&q=1","qs":[{"n":1,"q":"請詳細描述環境化學物質在人體的吸收與分布，並舉例說明。（25 分）","pt":25},{"n":2,"q":"請詳細說明基因毒性及非基因毒性致癌物的致癌機制，並舉例說明。（25 分）","pt":25},{"n":3,"q":"請詳細說明有機磷農藥、石綿及鉛三種化學物質的來源、吸收途徑，還有毒性表現及機制。（25 分）","pt":25},{"n":4,"q":"請舉出三種不同毒性的肺部毒性物質，並說明其來源，還有毒性表現及機制。（25 分）","pt":25}]}];
